    public List<AuditFinding> testGetAll() throws Throwable {
    LOGGER.info( "AuditFindingTest:testGetAll() - Retrieving Collection of AuditFindings:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all AuditFinding : " );
    List<AuditFinding> collection  = null;

    try {
        // call the static get method on the AuditFindingService
        collection = service.getAllAuditFinding();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            AuditFinding currEntity  = null;
            Iterator<AuditFinding> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getAuditFindingId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

